		/**
		* General math-related and numeric utility functions.
		*/
		class MathUtils {
			constructor() {}
			/**
			* Ends up being a bit faster than {@link Math#round(float)}. This merely rounds its
			* argument to the nearest int, where x.5 rounds up to x+1. Semantics of this shortcut
			* differ slightly from {@link Math#round(float)} in that half rounds down for negative
			* values. -2.5 rounds to -3, not -2. For purposes here it makes no difference.
			*
			* @param d real value to round
			* @return nearest {@code int}
			*/
			static round(d) {
				if (NaN === d) return 0;
				if (d <= Number.MIN_SAFE_INTEGER) return Number.MIN_SAFE_INTEGER;
				if (d >= Number.MAX_SAFE_INTEGER) return Number.MAX_SAFE_INTEGER;
				return d + (d < 0 ? -.5 : .5) | 0;
			}
			/**
			* @param aX point A x coordinate
			* @param aY point A y coordinate
			* @param bX point B x coordinate
			* @param bY point B y coordinate
			* @return Euclidean distance between points A and B
			*/
			static distance(aX, aY, bX, bY) {
				const xDiff = aX - bX;
				const yDiff = aY - bY;
				return Math.sqrt(xDiff * xDiff + yDiff * yDiff);
			}
			/**
			* @param aX point A x coordinate
			* @param aY point A y coordinate
			* @param bX point B x coordinate
			* @param bY point B y coordinate
			* @return Euclidean distance between points A and B
			*/
			/**
			* @param array values to sum
			* @return sum of values in array
			*/
			static sum(array) {
				let count = 0;
				for (let i = 0, length = array.length; i !== length; i++) {
					const a = array[i];
					count += a;
				}
				return count;
			}
		}
		/**
		* Ponyfill for Java's Float class.
		*/
		class Float {
			/**
			* SincTS has no difference between int and float, there's all numbers,
			* this is used only to polyfill Java code.
			*/
			static floatToIntBits(f) {
				return f;
			}
		}
		/**
		* The float max value in JS is the number max value.
		*/
		Float.MAX_VALUE = Number.MAX_SAFE_INTEGER;
		/**
		* <p>Encapsulates a point of interest in an image containing a barcode. Typically, this
		* would be the location of a finder pattern or the corner of the barcode, for example.</p>
		*
		* @author Sean Owen
		*/
		class ResultPoint {
			constructor(x, y) {
				this.x = x;
				this.y = y;
			}
			getX() {
				return this.x;
			}
			getY() {
				return this.y;
			}
			equals(other) {
				if (other instanceof ResultPoint) {
					const otherPoint = other;
					return this.x === otherPoint.x && this.y === otherPoint.y;
				}
				return false;
			}
			hashCode() {
				return 31 * Float.floatToIntBits(this.x) + Float.floatToIntBits(this.y);
			}
			toString() {
				return "(" + this.x + "," + this.y + ")";
			}
			/**
			* Orders an array of three ResultPoints in an order [A,B,C] such that AB is less than AC
			* and BC is less than AC, and the angle between BC and BA is less than 180 degrees.
			*
			* @param patterns array of three {@code ResultPoint} to order
			*/
			static orderBestPatterns(patterns) {
				const zeroOneDistance = this.distance(patterns[0], patterns[1]);
				const oneTwoDistance = this.distance(patterns[1], patterns[2]);
				const zeroTwoDistance = this.distance(patterns[0], patterns[2]);
				let pointA;
				let pointB;
				let pointC;
				if (oneTwoDistance >= zeroOneDistance && oneTwoDistance >= zeroTwoDistance) {
					pointB = patterns[0];
					pointA = patterns[1];
					pointC = patterns[2];
				} else if (zeroTwoDistance >= oneTwoDistance && zeroTwoDistance >= zeroOneDistance) {
					pointB = patterns[1];
					pointA = patterns[0];
					pointC = patterns[2];
				} else {
					pointB = patterns[2];
					pointA = patterns[0];
					pointC = patterns[1];
				}
				if (this.crossProductZ(pointA, pointB, pointC) < 0) {
					const temp = pointA;
					pointA = pointC;
					pointC = temp;
				}
				patterns[0] = pointA;
				patterns[1] = pointB;
				patterns[2] = pointC;
			}
			/**
			* @param pattern1 first pattern
			* @param pattern2 second pattern
			* @return distance between two points
			*/
			static distance(pattern1, pattern2) {
				return MathUtils.distance(pattern1.x, pattern1.y, pattern2.x, pattern2.y);
			}
			/**
			* Returns the z component of the cross product between vectors BC and BA.
			*/
			static crossProductZ(pointA, pointB, pointC) {
				const bX = pointB.x;
				const bY = pointB.y;
				return (pointC.x - bX) * (pointA.y - bY) - (pointC.y - bY) * (pointA.x - bX);
			}
		}
		/**
		* <p>Encapsulates the result of detecting a barcode in an image. This includes the raw
		* matrix of black/white pixels corresponding to the barcode, and possibly points of interest
		* in the image, like the location of finder patterns or corners of the barcode in the image.</p>
		*
		* @author Sean Owen
		*/
