		class GeneralAppIdDecoder {
			constructor(information) {
				this.buffer = new StringBuilder();
				this.information = information;
			}
			decodeAllCodes(buff, initialPosition) {
				let currentPosition = initialPosition;
				let remaining = null;
				do {
					let info = this.decodeGeneralPurposeField(currentPosition, remaining);
					let parsedFields = FieldParser.parseFieldsInGeneralPurpose(info.getNewString());
					if (parsedFields != null) buff.append(parsedFields);
					if (info.isRemaining()) remaining = "" + info.getRemainingValue();
					else remaining = null;
					if (currentPosition === info.getNewPosition()) break;
					currentPosition = info.getNewPosition();
				} while (true);
				return buff.toString();
			}
			isStillNumeric(pos) {
				if (pos + 7 > this.information.getSize()) return pos + 4 <= this.information.getSize();
				for (let i = pos; i < pos + 3; ++i) if (this.information.get(i)) return true;
				return this.information.get(pos + 3);
			}
			decodeNumeric(pos) {
				if (pos + 7 > this.information.getSize()) {
					let numeric = this.extractNumericValueFromBitArray(pos, 4);
					if (numeric === 0) return new DecodedNumeric(this.information.getSize(), DecodedNumeric.FNC1, DecodedNumeric.FNC1);
					return new DecodedNumeric(this.information.getSize(), numeric - 1, DecodedNumeric.FNC1);
				}
				let numeric = this.extractNumericValueFromBitArray(pos, 7);
				let digit1 = (numeric - 8) / 11;
				let digit2 = (numeric - 8) % 11;
				return new DecodedNumeric(pos + 7, digit1, digit2);
			}
			extractNumericValueFromBitArray(pos, bits) {
				return GeneralAppIdDecoder.extractNumericValueFromBitArray(this.information, pos, bits);
			}
			static extractNumericValueFromBitArray(information, pos, bits) {
				let value = 0;
				for (let i = 0; i < bits; ++i) if (information.get(pos + i)) value |= 1 << bits - i - 1;
				return value;
			}
			decodeGeneralPurposeField(pos, remaining) {
				this.buffer.setLengthToZero();
				if (remaining != null) this.buffer.append(remaining);
				this.current.setPosition(pos);
				let lastDecoded = this.parseBlocks();
				if (lastDecoded != null && lastDecoded.isRemaining()) return new DecodedInformation(this.current.getPosition(), this.buffer.toString(), lastDecoded.getRemainingValue());
				return new DecodedInformation(this.current.getPosition(), this.buffer.toString());
			}
			parseBlocks() {
				let isFinished;
				let result;
				do {
					let initialPosition = this.current.getPosition();
					if (this.current.isAlpha()) {
						result = this.parseAlphaBlock();
						isFinished = result.isFinished();
					} else if (this.current.isIsoIec646()) {
						result = this.parseIsoIec646Block();
						isFinished = result.isFinished();
					} else {
						result = this.parseNumericBlock();
						isFinished = result.isFinished();
					}
					if (!(initialPosition !== this.current.getPosition()) && !isFinished) break;
				} while (!isFinished);
				return result.getDecodedInformation();
			}
			parseNumericBlock() {
				while (this.isStillNumeric(this.current.getPosition())) {
					let numeric = this.decodeNumeric(this.current.getPosition());
					this.current.setPosition(numeric.getNewPosition());
					if (numeric.isFirstDigitFNC1()) {
						let information;
						if (numeric.isSecondDigitFNC1()) information = new DecodedInformation(this.current.getPosition(), this.buffer.toString());
						else information = new DecodedInformation(this.current.getPosition(), this.buffer.toString(), numeric.getSecondDigit());
						return new BlockParsedResult(true, information);
					}
					this.buffer.append(numeric.getFirstDigit());
					if (numeric.isSecondDigitFNC1()) {
						let information = new DecodedInformation(this.current.getPosition(), this.buffer.toString());
						return new BlockParsedResult(true, information);
					}
					this.buffer.append(numeric.getSecondDigit());
				}
				if (this.isNumericToAlphaNumericLatch(this.current.getPosition())) {
					this.current.setAlpha();
					this.current.incrementPosition(4);
				}
				return new BlockParsedResult(false);
			}
			parseIsoIec646Block() {
				while (this.isStillIsoIec646(this.current.getPosition())) {
					let iso = this.decodeIsoIec646(this.current.getPosition());
					this.current.setPosition(iso.getNewPosition());
					if (iso.isFNC1()) {
						let information = new DecodedInformation(this.current.getPosition(), this.buffer.toString());
						return new BlockParsedResult(true, information);
					}
					this.buffer.append(iso.getValue());
				}
				if (this.isAlphaOr646ToNumericLatch(this.current.getPosition())) {
					this.current.incrementPosition(3);
					this.current.setNumeric();
				} else if (this.isAlphaTo646ToAlphaLatch(this.current.getPosition())) {
					if (this.current.getPosition() + 5 < this.information.getSize()) this.current.incrementPosition(5);
					else this.current.setPosition(this.information.getSize());
					this.current.setAlpha();
				}
				return new BlockParsedResult(false);
			}
			parseAlphaBlock() {
				while (this.isStillAlpha(this.current.getPosition())) {
					let alpha = this.decodeAlphanumeric(this.current.getPosition());
					this.current.setPosition(alpha.getNewPosition());
					if (alpha.isFNC1()) {
						let information = new DecodedInformation(this.current.getPosition(), this.buffer.toString());
						return new BlockParsedResult(true, information);
					}
					this.buffer.append(alpha.getValue());
				}
				if (this.isAlphaOr646ToNumericLatch(this.current.getPosition())) {
					this.current.incrementPosition(3);
					this.current.setNumeric();
				} else if (this.isAlphaTo646ToAlphaLatch(this.current.getPosition())) {
					if (this.current.getPosition() + 5 < this.information.getSize()) this.current.incrementPosition(5);
					else this.current.setPosition(this.information.getSize());
					this.current.setIsoIec646();
				}
				return new BlockParsedResult(false);
			}
			isStillIsoIec646(pos) {
				if (pos + 5 > this.information.getSize()) return false;
				let fiveBitValue = this.extractNumericValueFromBitArray(pos, 5);
				if (fiveBitValue >= 5 && fiveBitValue < 16) return true;
				if (pos + 7 > this.information.getSize()) return false;
				let sevenBitValue = this.extractNumericValueFromBitArray(pos, 7);
				if (sevenBitValue >= 64 && sevenBitValue < 116) return true;
				if (pos + 8 > this.information.getSize()) return false;
				let eightBitValue = this.extractNumericValueFromBitArray(pos, 8);
				return eightBitValue >= 232 && eightBitValue < 253;
			}
			decodeIsoIec646(pos) {
				let fiveBitValue = this.extractNumericValueFromBitArray(pos, 5);
				if (fiveBitValue === 15) return new DecodedChar(pos + 5, DecodedChar.FNC1);
				if (fiveBitValue >= 5 && fiveBitValue < 15) return new DecodedChar(pos + 5, "0" + (fiveBitValue - 5));
				let sevenBitValue = this.extractNumericValueFromBitArray(pos, 7);
				if (sevenBitValue >= 64 && sevenBitValue < 90) return new DecodedChar(pos + 7, "" + (sevenBitValue + 1));
				if (sevenBitValue >= 90 && sevenBitValue < 116) return new DecodedChar(pos + 7, "" + (sevenBitValue + 7));
				let eightBitValue = this.extractNumericValueFromBitArray(pos, 8);
				let c;
				switch (eightBitValue) {
					case 232:
						c = "!";
						break;
					case 233:
						c = "\"";
						break;
					case 234:
						c = "%";
						break;
					case 235:
						c = "&";
						break;
					case 236:
						c = "'";
						break;
					case 237:
						c = "(";
						break;
					case 238:
						c = ")";
						break;
					case 239:
						c = "*";
						break;
					case 240:
						c = "+";
						break;
					case 241:
						c = ",";
						break;
					case 242:
						c = "-";
						break;
					case 243:
						c = ".";
						break;
					case 244:
						c = "/";
						break;
					case 245:
						c = ":";
						break;
					case 246:
						c = ";";
						break;
					case 247:
						c = "<";
						break;
					case 248:
						c = "=";
						break;
					case 249:
						c = ">";
						break;
					case 250:
						c = "?";
						break;
					case 251:
						c = "_";
						break;
					case 252:
						c = " ";
						break;
					default: throw new FormatException();
				}
				return new DecodedChar(pos + 8, c);
			}
			isStillAlpha(pos) {
				if (pos + 5 > this.information.getSize()) return false;
				let fiveBitValue = this.extractNumericValueFromBitArray(pos, 5);
				if (fiveBitValue >= 5 && fiveBitValue < 16) return true;
				if (pos + 6 > this.information.getSize()) return false;
				let sixBitValue = this.extractNumericValueFromBitArray(pos, 6);
				return sixBitValue >= 16 && sixBitValue < 63;
			}
			decodeAlphanumeric(pos) {
				let fiveBitValue = this.extractNumericValueFromBitArray(pos, 5);
				if (fiveBitValue === 15) return new DecodedChar(pos + 5, DecodedChar.FNC1);
				if (fiveBitValue >= 5 && fiveBitValue < 15) return new DecodedChar(pos + 5, "0" + (fiveBitValue - 5));
				let sixBitValue = this.extractNumericValueFromBitArray(pos, 6);
				if (sixBitValue >= 32 && sixBitValue < 58) return new DecodedChar(pos + 6, "" + (sixBitValue + 33));
				let c;
				switch (sixBitValue) {
					case 58:
						c = "*";
						break;
					case 59:
						c = ",";
						break;
					case 60:
						c = "-";
						break;
					case 61:
						c = ".";
						break;
					case 62:
						c = "/";
						break;
					default: throw new IllegalStateException("Decoding invalid alphanumeric value: " + sixBitValue);
				}
				return new DecodedChar(pos + 6, c);
			}
			isAlphaTo646ToAlphaLatch(pos) {
				if (pos + 1 > this.information.getSize()) return false;
				for (let i = 0; i < 5 && i + pos < this.information.getSize(); ++i) if (i === 2) {
					if (!this.information.get(pos + 2)) return false;
				} else if (this.information.get(pos + i)) return false;
				return true;
			}
			isAlphaOr646ToNumericLatch(pos) {
				if (pos + 3 > this.information.getSize()) return false;
				for (let i = pos; i < pos + 3; ++i) if (this.information.get(i)) return false;
				return true;
			}
			isNumericToAlphaNumericLatch(pos) {
				if (pos + 1 > this.information.getSize()) return false;
				for (let i = 0; i < 4 && i + pos < this.information.getSize(); ++i) if (this.information.get(pos + i)) return false;
				return true;
			}
		}
		class AbstractExpandedDecoder {
			constructor(information) {
				this.information = information;
				this.generalDecoder = new GeneralAppIdDecoder(information);
			}
			getInformation() {
				return this.information;
			}
			getGeneralDecoder() {
				return this.generalDecoder;
			}
		}
		class AI01decoder extends AbstractExpandedDecoder {
			constructor(information) {
				super(information);
			}
			encodeCompressedGtin(buf, currentPos) {
				buf.append("(01)");
				let initialPosition = buf.length();
				buf.append("9");
				this.encodeCompressedGtinWithoutAI(buf, currentPos, initialPosition);
			}
			encodeCompressedGtinWithoutAI(buf, currentPos, initialBufferPosition) {
				for (let i = 0; i < 4; ++i) {
					let currentBlock = this.getGeneralDecoder().extractNumericValueFromBitArray(currentPos + 10 * i, 10);
					if (currentBlock / 100 === 0) buf.append("0");
					if (currentBlock / 10 === 0) buf.append("0");
					buf.append(currentBlock);
				}
				AI01decoder.appendCheckDigit(buf, initialBufferPosition);
			}
			static appendCheckDigit(buf, currentPos) {
				let checkDigit = 0;
				for (let i = 0; i < 13; i++) {
					let digit = buf.charAt(i + currentPos).charCodeAt(0) - "0".charCodeAt(0);
					checkDigit += (i & 1) === 0 ? 3 * digit : digit;
				}
				checkDigit = 10 - checkDigit % 10;
				if (checkDigit === 10) checkDigit = 0;
				buf.append(checkDigit);
			}
		}
