// src/utils/escpos.ts
var EscPosEncoder = class {
	constructor() {
		this.buffer = [];
		this.init();
	}
	init() {
		this.buffer.push(27, 64);
		return this;
	}
	align(align) {
		const val = align === "center" ? 1 : align === "right" ? 2 : 0;
		this.buffer.push(27, 97, val);
		return this;
	}
	bold(enable) {
		this.buffer.push(27, 69, enable ? 1 : 0);
		return this;
	}
	textSize(size) {
		if (size === "large") this.buffer.push(27, 33, 48);
		else if (size === "double") this.buffer.push(27, 33, 16);
		else this.buffer.push(27, 33, 0);
		return this;
	}
	text(str) {
		const bytes = new TextEncoder().encode(str);
		for (let i = 0; i < bytes.length; i++) this.buffer.push(bytes[i]);
		return this;
	}
	line(str = "") {
		this.text(str);
		this.buffer.push(10);
		return this;
	}
	divider(char = "-", width = 32) {
		this.line(char.repeat(width));
		return this;
	}
	tableRow(left, right, width = 32) {
		const spaceNeeded = width - (left.length + right.length);
		if (spaceNeeded <= 0) {
			this.line(left);
			this.line(" ".repeat(Math.max(0, width - right.length)) + right);
		} else this.line(left + " ".repeat(spaceNeeded) + right);
		return this;
	}
	feed(lines = 3) {
		for (let i = 0; i < lines; i++) this.buffer.push(10);
		return this;
	}
	cut() {
		this.buffer.push(29, 86, 65, 3);
		return this;
	}
	getBytes() {
		return new Uint8Array(this.buffer);
	}
	toBase64() {
		const binary = String.fromCharCode.apply(null, Array.from(this.getBytes()));
		return btoa(binary);
	}
};
/**
* Builds the complete ESC/POS binary receipt for a sale
*/
function buildEscPosReceipt(sale, profile, paperWidth = 32) {
	const enc = new EscPosEncoder();
	enc.align("center");
	enc.textSize("large").bold(true);
	enc.line(profile.shopName || "Sahoj Dokan POS");
	enc.textSize("normal").bold(false);
	if (profile.address) enc.line(profile.address);
	enc.line(`Mobile: ${profile.phone}`);
	enc.divider("=", paperWidth);
	enc.align("left");
	enc.tableRow(`Inv: #${sale.invoiceNo}`, new Date(sale.date).toLocaleDateString("en-GB"), paperWidth);
	enc.tableRow(`Customer:`, sale.customerName || "Cash Buyer", paperWidth);
	enc.divider("-", paperWidth);
	enc.tableRow("Item / Qty x Rate", "Total (Tk)", paperWidth);
	enc.divider("-", paperWidth);
	sale.items.forEach((item, index) => {
		enc.line(`${index + 1}. ${item.productName}`);
		const qtyRate = `   ${item.quantity} ${item.unit} x Tk ${item.unitPrice}`;
		const total = `Tk ${item.totalPrice}`;
		enc.tableRow(qtyRate, total, paperWidth);
	});
	enc.divider("-", paperWidth);
	enc.tableRow("Subtotal:", `Tk ${sale.subTotal}`, paperWidth);
	if (sale.discount > 0) enc.tableRow("Discount:", `-Tk ${sale.discount}`, paperWidth);
	enc.bold(true);
	enc.tableRow("GRAND TOTAL:", `Tk ${sale.grandTotal}`, paperWidth);
	enc.bold(false);
	enc.tableRow("Paid Amount:", `Tk ${sale.paidAmount}`, paperWidth);
	if (sale.dueAmount > 0) {
		enc.bold(true);
		enc.tableRow("DUE (Baki):", `Tk ${sale.dueAmount}`, paperWidth);
		enc.bold(false);
	} else enc.tableRow("Change Return:", `Tk ${sale.changeAmount}`, paperWidth);
	enc.divider("=", paperWidth);
	enc.align("center");
	enc.line("Thank you! Please visit again.");
	enc.line("Powered by Sahoj Dokan POS");
	enc.feed(3);
	enc.cut();
	return enc;
}
/**
* Builds the complete ESC/POS binary receipt for Day Close closing slip
*/
function buildEscPosDayCloseReceipt(data, paperWidth = 32) {
	const enc = new EscPosEncoder();
	enc.align("center");
	enc.textSize("large").bold(true);
	enc.line(data.shopName || "Sahoj Dokan POS");
	enc.textSize("normal").bold(false);
	if (data.address) enc.line(data.address);
	enc.line(`Mobile: ${data.phone}`);
	enc.divider("=", paperWidth);
	enc.bold(true);
	enc.line("DAILY DAY CLOSE SLIP");
	enc.line("(দৈনিক দোকান ক্লোজিং স্লিপ)");
	enc.bold(false);
	enc.divider("-", paperWidth);
	enc.align("left");
	enc.tableRow("Date / Time:", `${data.dateStr} ${data.timeStr}`, paperWidth);
	enc.divider("-", paperWidth);
	enc.tableRow("Opening Cash:", `Tk ${data.openingCash}`, paperWidth);
	enc.tableRow("Total Sales:", `Tk ${data.totalSales}`, paperWidth);
	enc.tableRow(" - Cash Sales:", `Tk ${data.cashSales}`, paperWidth);
	if (data.dueSales > 0) enc.tableRow(" - Due Sales:", `Tk ${data.dueSales}`, paperWidth);
	enc.tableRow("Gross Profit:", `Tk ${data.totalProfit}`, paperWidth);
	enc.divider("-", paperWidth);
	if (data.customerDueCollected > 0) enc.tableRow("Due Collected In:", `Tk ${data.customerDueCollected}`, paperWidth);
	if (data.ownerDeposit > 0) enc.tableRow("Owner Capital In:", `Tk ${data.ownerDeposit}`, paperWidth);
	enc.tableRow("Cash Purchases:", `Tk ${data.cashPurchases}`, paperWidth);
	enc.tableRow("Shop Expenses:", `Tk ${data.shopExpenses}`, paperWidth);
	if (data.supplierDuePaid > 0) enc.tableRow("Supplier Paid:", `Tk ${data.supplierDuePaid}`, paperWidth);
	if (data.ownerWithdrawal > 0) enc.tableRow("Owner Withdraw:", `Tk ${data.ownerWithdrawal}`, paperWidth);
	enc.divider("=", paperWidth);
	enc.bold(true);
	enc.textSize("double");
	enc.tableRow("EXPECTED CASH:", `Tk ${data.expectedCash}`, paperWidth);
	enc.textSize("normal");
	if (typeof data.actualCash === "number" && !isNaN(data.actualCash)) {
		enc.tableRow("Physical Drawer:", `Tk ${data.actualCash}`, paperWidth);
		const diff = data.difference || 0;
		const diffText = diff === 0 ? "MATCHED (Mil ache)" : diff > 0 ? `+Tk ${diff} (Extra)` : `-Tk ${Math.abs(diff)} (Short)`;
		enc.tableRow("Status:", diffText, paperWidth);
	}
	enc.bold(false);
	if (data.note) {
		enc.divider("-", paperWidth);
		enc.line(`Note: ${data.note}`);
	}
	enc.divider("=", paperWidth);
	enc.align("center");
	enc.line("Shop Closed Successfully.");
	enc.line("Powered by Sahoj Dokan POS");
	enc.feed(3);
	enc.cut();
	return enc;
}
